<template>
  <section class="wechat-content">
    <PageHeader title="图文与群发" description="图文草稿、群发任务和双人审批；真实群发默认关闭。">
      <template #actions><el-button @click="loadAccounts">刷新</el-button></template>
    </PageHeader>
    <el-alert type="warning" :closable="false" show-icon title="真实群发必须服务端显式启用、任务审批通过，并由另一名管理员执行；模板业务通知不能替代群发。" />
    <el-card shadow="never"><div class="toolbar"><div><strong>运营公众号</strong><span>图文和群发任务只属于当前公众号</span></div><el-select v-model="accountId" placeholder="选择公众号" style="width:320px" @change="loadAll"><el-option v-for="item in accounts" :key="item.id" :label="`${item.name} · ${item.appId}`" :value="item.id" /></el-select></div></el-card>
    <el-empty v-if="!accountId" description="请先绑定公众号" />
    <el-tabs v-else v-model="active" class="content-tabs" @tab-change="loadTab">
      <el-tab-pane label="图文草稿" name="articles">
        <div class="panel-head"><div><strong>图文草稿</strong><span>先保存本地草稿；推送微信草稿和公开发布需后续单独操作。</span></div><el-button type="primary" @click="openArticle()">新增草稿</el-button></div>
        <DataTable :loading="busy" :data="articles" row-key="id" empty-text="还没有图文草稿"><el-table-column prop="title" label="标题" min-width="220"/><el-table-column prop="author" label="作者" width="120"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="remoteMediaId" label="微信草稿" min-width="180" show-overflow-tooltip/><el-table-column prop="updatedAt" label="更新时间" min-width="170"/><el-table-column label="操作" width="240" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openArticle(row)">编辑</el-button><el-button v-if="row.status==='DRAFT'" link type="primary" @click="pushArticle(row)">推送草稿</el-button><el-button v-if="row.status==='PUSHED'" link type="success" @click="publishArticle(row)">发布</el-button><el-button link type="danger" @click="removeArticle(row)">删除</el-button></template></el-table-column></DataTable>
      </el-tab-pane>
      <el-tab-pane label="群发审批" name="tasks">
        <div class="panel-head"><div><strong>群发任务</strong><span>提交后由另一名管理员审批；发送前必须开启服务端群发开关。</span></div><el-button type="primary" @click="openTask()">新增任务</el-button></div>
        <DataTable :loading="busy" :data="tasks" row-key="id" empty-text="还没有群发任务"><el-table-column prop="name" label="任务" min-width="180"/><el-table-column prop="targetType" label="范围" width="110"/><el-table-column prop="msgType" label="类型" width="100"/><el-table-column prop="status" label="状态" width="140"/><el-table-column prop="updatedAt" label="更新时间" min-width="170"/><el-table-column label="操作" width="260" fixed="right"><template #default="{ row }"><el-button v-if="['DRAFT','REJECTED'].includes(row.status)" link type="primary" @click="openTask(row)">编辑</el-button><el-button v-if="['DRAFT','REJECTED'].includes(row.status)" link type="primary" @click="act(row,'submit')">提交</el-button><el-button v-if="row.status==='PENDING_APPROVAL'" link type="success" @click="act(row,'approve')">批准</el-button><el-button v-if="row.status==='PENDING_APPROVAL'" link type="danger" @click="act(row,'reject')">驳回</el-button><el-button v-if="row.status==='APPROVED'" link type="danger" @click="send(row)">发送</el-button></template></el-table-column></DataTable>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="articleDialog" :title="articleForm.id?'编辑图文草稿':'新增图文草稿'" width="min(760px,96vw)" destroy-on-close><el-form label-position="top"><el-form-item label="标题"><el-input v-model="articleForm.title" maxlength="120"/></el-form-item><div class="grid"><el-form-item label="作者"><el-input v-model="articleForm.author" maxlength="64"/></el-form-item><el-form-item label="封面素材 Media ID"><el-input v-model="articleForm.coverMediaId" maxlength="128"/></el-form-item></div><el-form-item label="摘要"><el-input v-model="articleForm.digest" maxlength="500"/></el-form-item><el-form-item label="正文 HTML"><el-input v-model="articleForm.contentHtml" type="textarea" :rows="12" maxlength="1000000"/></el-form-item></el-form><template #footer><el-button @click="articleDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveArticle">保存</el-button></template></el-dialog>
    <el-dialog v-model="taskDialog" :title="taskForm.id?'编辑群发任务':'新增群发任务'" width="min(620px,94vw)" destroy-on-close><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="taskForm.name" maxlength="80"/></el-form-item><div class="grid"><el-form-item label="范围"><el-select v-model="taskForm.targetType"><el-option label="全部粉丝" value="ALL"/><el-option label="按标签" value="TAG"/><el-option label="指定 OpenID" value="OPENIDS"/></el-select></el-form-item><el-form-item label="消息类型"><el-select v-model="taskForm.msgType"><el-option label="文字" value="TEXT"/><el-option label="图片" value="IMAGE"/><el-option label="图文" value="MPNEWS"/></el-select></el-form-item></div><el-form-item v-if="taskForm.targetType==='TAG'" label="标签 ID"><el-input v-model="taskForm.tagId"/></el-form-item><el-form-item v-if="taskForm.targetType==='OPENIDS'" label="OpenID（逗号或换行分隔）"><el-input v-model="taskForm.openids" type="textarea" :rows="4"/></el-form-item><el-form-item v-if="taskForm.msgType==='TEXT'" label="文字内容"><el-input v-model="taskForm.text" type="textarea" :rows="5" maxlength="2000"/></el-form-item><el-form-item v-else label="素材 Media ID"><el-input v-model="taskForm.mediaId" maxlength="128"/></el-form-item></el-form><template #footer><el-button @click="taskDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveTask">保存</el-button></template></el-dialog>
  </section>
</template>
<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import PageHeader from '@/components/PageHeader.vue'
import DataTable from '@/components/DataTable.vue'
import { getWechatAccounts, getWechatArticles, saveWechatArticle, deleteWechatArticle, pushWechatArticle, publishWechatArticle, getWechatMassSends, saveWechatMassSend, transitionWechatMassSend, sendWechatMassSend } from '@/api/wechat-operations'
const accounts=ref([]),accountId=ref(''),active=ref('articles'),articles=ref([]),tasks=ref([]),busy=ref(false),saving=ref(false),articleDialog=ref(false),taskDialog=ref(false)
const articleForm=reactive({id:null,title:'',author:'',digest:'',contentHtml:'',coverUrl:'',coverMediaId:''})
const taskForm=reactive({id:null,name:'',targetType:'ALL',msgType:'TEXT',tagId:'',openids:'',text:'',mediaId:''})
async function loadAccounts(){busy.value=true;try{accounts.value=(await getWechatAccounts()).data||[];if(!accountId.value||!accounts.value.some(x=>x.id===accountId.value))accountId.value=accounts.value[0]?.id||'';await loadTab()}catch(e){ElMessage.error(e?.message||'公众号读取失败')}finally{busy.value=false}}
async function loadAll(){await loadTab()}
async function loadTab(){if(!accountId.value)return;busy.value=true;try{if(active.value==='articles')articles.value=(await getWechatArticles(accountId.value)).data||[];else tasks.value=(await getWechatMassSends(accountId.value)).data||[]}catch(e){ElMessage.error(e?.message||'内容读取失败')}finally{busy.value=false}}
function openArticle(row=null){Object.assign(articleForm,{id:null,title:'',author:'',digest:'',contentHtml:'',coverUrl:'',coverMediaId:''},row?{id:row.id,title:row.title,author:row.author||'',digest:row.digest||'',contentHtml:row.contentHtml||'',coverUrl:row.coverUrl||'',coverMediaId:row.coverMediaId||''}:{});articleDialog.value=true}
async function saveArticle(){if(!articleForm.title.trim())return ElMessage.warning('请填写标题');saving.value=true;try{await saveWechatArticle(accountId.value,articleForm.id,articleForm);articleDialog.value=false;ElMessage.success('图文草稿已保存');await loadTab()}catch(e){ElMessage.error(e?.message||'保存失败')}finally{saving.value=false}}
async function removeArticle(row){try{await ElMessageBox.confirm(`确认删除“${row.title}”？`,'删除图文草稿',{type:'warning'})}catch{return}try{await deleteWechatArticle(accountId.value,row.id);ElMessage.success('草稿已删除');await loadTab()}catch(e){ElMessage.error(e?.message||'删除失败')}}
async function pushArticle(row){try{await ElMessageBox.confirm('推送会创建或覆盖微信草稿，确认继续？','推送微信草稿',{type:'warning'})}catch{return}try{await pushWechatArticle(accountId.value,row.id);ElMessage.success('已推送微信草稿');await loadTab()}catch(e){ElMessage.error(e?.message||'推送失败')}}
async function publishArticle(row){try{await ElMessageBox.confirm('公开发布后读者可见，确认已核对标题、封面和正文？','发布公众号图文',{type:'warning',confirmButtonText:'确认发布'})}catch{return}try{await publishWechatArticle(accountId.value,row.id);ElMessage.success('图文发布请求已提交');await loadTab()}catch(e){ElMessage.error(e?.message||'发布失败')}}
function openTask(row=null){Object.assign(taskForm,{id:null,name:'',targetType:'ALL',msgType:'TEXT',tagId:'',openids:'',text:'',mediaId:''},row?{id:row.id,name:row.name,targetType:row.targetType,msgType:row.msgType,tagId:row.target?.tagId||'',openids:(row.target?.openids||[]).join('\n'),text:row.content?.text||'',mediaId:row.content?.mediaId||''}:{});taskDialog.value=true}
async function saveTask(){if(!taskForm.name.trim())return ElMessage.warning('请填写任务名称');const target=taskForm.targetType==='TAG'?{tagId:Number(taskForm.tagId)}:taskForm.targetType==='OPENIDS'?{openids:taskForm.openids.split(/[\s,]+/).filter(Boolean)}:{};const content=taskForm.msgType==='TEXT'?{text:taskForm.text}:{mediaId:taskForm.mediaId};saving.value=true;try{await saveWechatMassSend(accountId.value,taskForm.id,{name:taskForm.name,targetType:taskForm.targetType,msgType:taskForm.msgType,target,content});taskDialog.value=false;ElMessage.success('群发任务已保存');await loadTab()}catch(e){ElMessage.error(e?.message||'保存失败')}finally{saving.value=false}}
async function act(row,action){try{await ElMessageBox.confirm(`确认${action==='submit'?'提交审批':action==='approve'?'批准':'驳回'}“${row.name}”？`,'群发审批',{type:'warning'})}catch{return}try{await transitionWechatMassSend(accountId.value,row.id,action);ElMessage.success('状态已更新');await loadTab()}catch(e){ElMessage.error(e?.message||'操作失败')}}
async function send(row){try{await ElMessageBox.confirm('真实群发不可撤回，确认已核对内容、范围、配额并已获得单独授权？','执行真实群发',{type:'warning',confirmButtonText:'确认发送'})}catch{return}try{await sendWechatMassSend(accountId.value,row.id);ElMessage.success('群发请求已提交');await loadTab()}catch(e){ElMessage.error(e?.message||'群发失败')}}
onMounted(loadAccounts)
</script>
<style scoped>.wechat-content{display:grid;gap:16px}.toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px}.toolbar strong,.toolbar span{display:block}.toolbar strong{font-size:14px}.toolbar span{margin-top:4px;color:var(--el-text-color-secondary);font-size:12px}.content-tabs{background:var(--el-bg-color);border:1px solid var(--el-border-color-light);border-radius:14px;padding:0 18px 18px}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:8px 0 14px}.panel-head strong,.panel-head span{display:block}.panel-head strong{font-size:14px}.panel-head span{margin-top:4px;color:var(--el-text-color-secondary);font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}@media(max-width:768px){.toolbar,.panel-head{align-items:stretch;flex-direction:column}.toolbar :deep(.el-select){width:100%!important}.grid{grid-template-columns:1fr}}</style>
